C++一般模板完全背包#include&lt;bits/stdc++.h&gt;using namespace std;int main()&#123;    int n,W;    cin&gt;&gt;n&gt;&gt;W;    vector&lt;int&gt; w(n+1),v(n+1);    for(int i=1;i&lt;=n;i++)cin&gt;&gt;w[i]&gt;&gt;v[i];    vector&lt;int&gt; dp(W+1,0);    for(int i=1;i&lt;=n;i++)&#123;            for(int j=w[i];j&lt;=W;j++)&#123;            dp[j]=max(dp[j],dp[j-w[i]]+v[i]);        &#125;    &#125;    cout&lt;&lt;dp[W]&lt;&lt;endl;    return 0;&#125;
多重背包#include&lt;bits/stdc++.h&gt;using namespace std;int main()&#123;    int n,W;    cin&gt;&gt;n&gt;&gt;W;    vector&lt;int&gt; w(n+1),v(n+1),c(n+1);    for(int i=1;i&lt;=n;i++)cin&gt;&gt;w[i]&gt;&gt;v[i]&gt;&gt;c[i];    vector&lt;int&gt; dp(W+1,0);    for(int i=1;i&lt;=n;i++)&#123;        for(int k=1;k&lt;=c[i];k++)&#123;                   for(int j=w[i];j&lt;=W;j--)&#123;                dp[j]=max(dp[j],dp[j-w[i]]+v[i]);            &#125;        &#125;    &#125;    cout&lt;&lt;dp[W]&lt;&lt;endl;    return 0;&#125;
0&#x2F;1背包#include&lt;bits/stdc++.h&gt;using namespace std;int main()&#123;    int n,W;    cin&gt;&gt;n&gt;&gt;W;    vector&lt;int&gt; w(n+1),v(n+1);    for(int i=1;i&lt;=n;i++)cin&gt;&gt;w[i]&gt;&gt;v[i];    vector&lt;int&gt; dp(W+1,0);    for(int i=1;i&lt;=n;i++)&#123;        for(int j=W;j&gt;=w[i];j--)&#123;            dp[j]=max(dp[j],dp[j-w[i]]+v[i]);        &#125;    &#125;    cout&lt;&lt;dp[W]&lt;&lt;endl;&#125;
